def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me = history[-1][0]
    last_opp = history[-1][1]

    start = 0 if n < 10 else n - 10
    opp_c = 0
    rec_opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1
            if i >= start:
                rec_opp_c += 1

    opp_d = n - opp_c
    rec_len = n - start
    opp_rate = float(opp_c) / float(n)
    rec_rate = float(rec_opp_c) / float(rec_len)
    base_est = 0.35 * opp_rate + 0.65 * rec_rate

    mean = False
    if n >= 2 and opp_c == 0:
        mean = True
    if n >= 5 and rec_opp_c == 0 and base_est < 0.35:
        mean = True
    if n >= 6 and rec_opp_c <= 1 and base_est < 0.18:
        mean = True
    if n >= 15 and opp_rate < 0.18 and rec_opp_c <= 2:
        mean = True

    if mean:
        return 'D'

    cnt00C = 0
    cnt00D = 0
    cnt01C = 0
    cnt01D = 0
    cnt10C = 0
    cnt10D = 0
    cnt11C = 0
    cnt11D = 0

    for i in range(1, n):
        pm = 0 if history[i - 1][0] == 'C' else 1
        po = 0 if history[i - 1][1] == 'C' else 1
        co = 0 if history[i][1] == 'C' else 1
        if pm == 0:
            if po == 0:
                if co == 0:
                    cnt00C += 1
                else:
                    cnt00D += 1
            else:
                if co == 0:
                    cnt01C += 1
                else:
                    cnt01D += 1
        else:
            if po == 0:
                if co == 0:
                    cnt10C += 1
                else:
                    cnt10D += 1
            else:
                if co == 0:
                    cnt11C += 1
                else:
                    cnt11D += 1

    after_c_c = cnt00C + cnt01C
    after_c_d = cnt00D + cnt01D
    after_d_c = cnt10C + cnt11C
    after_d_d = cnt10D + cnt11D

    if last_me == 'D' and last_opp == 'D' and n <= 90:
        if base_est > 0.45 or rec_opp_c >= 4 or opp_rate >= 0.6:
            return 'C'

    if last_me == 'C' and last_opp == 'D' and n >= 3 and n <= 90:
        if history[-2][0] == 'D' and history[-2][1] == 'C':
            if base_est > 0.45 and rec_opp_c >= 2:
                return 'C'

    if opp_d == 0 and last_me == 'D' and last_opp == 'C' and after_d_c < 2:
        return 'C'

    if opp_d == 0 and last_me == 'C' and last_opp == 'C':
        if 15 <= n <= 70 and after_d_c < 2:
            if rng.random() < 0.15:
                return 'D'

    alpha = 4.0
    tc = after_c_c + after_c_d
    if tc == 0:
        p_c = base_est
    else:
        p_c = (float(after_c_c) + alpha * base_est) / float(tc + alpha)

    p_d_prior = 0.06 + 0.08 * base_est
    td = after_d_c + after_d_d

    if after_d_d == 0:
        if opp_d == 0:
            if after_d_c >= 2:
                p_d = 0.85
            elif after_d_c == 1:
                p_d = 0.35
            else:
                p_d = p_d_prior
        else:
            if td == 0:
                p_d = p_d_prior
            else:
                p_d = (float(after_d_c) + alpha * p_d_prior) / float(td + alpha)
            if after_d_c >= 2 and base_est > 0.5:
                p_d = max(p_d, 0.45)
    else:
        if td == 0:
            p_d = p_d_prior
        else:
            p_d = (float(after_d_c) + alpha * p_d_prior) / float(td + alpha)
        if after_d_d >= 2 and after_d_d >= after_d_c:
            p_d = min(p_d, 0.18)
        elif after_d_c > after_d_d and after_d_c >= 3 and base_est > 0.5:
            p_d = max(p_d, 0.55)

    if p_c < 0.02:
        p_c = 0.02
    elif p_c > 0.98:
        p_c = 0.98
    if p_d < 0.02:
        p_d = 0.02
    elif p_d > 0.98:
        p_d = 0.98

    as_alpha = 2.0
    t = cnt00C + cnt00D
    if t == 0:
        sp00 = p_c
    else:
        sp00 = (float(cnt00C) + as_alpha * p_c) / float(t + as_alpha)
    if sp00 < 0.02:
        sp00 = 0.02
    elif sp00 > 0.98:
        sp00 = 0.98

    t = cnt01C + cnt01D
    if t == 0:
        sp01 = p_c
    else:
        sp01 = (float(cnt01C) + as_alpha * p_c) / float(t + as_alpha)
    if sp01 < 0.02:
        sp01 = 0.02
    elif sp01 > 0.98:
        sp01 = 0.98

    t = cnt10C + cnt10D
    if t == 0:
        sp10 = p_d
    else:
        sp10 = (float(cnt10C) + as_alpha * p_d) / float(t + as_alpha)
    if sp10 < 0.02:
        sp10 = 0.02
    elif sp10 > 0.98:
        sp10 = 0.98

    t = cnt11C + cnt11D
    if t == 0:
        sp11 = p_d
    else:
        sp11 = (float(cnt11C) + as_alpha * p_d) / float(t + as_alpha)
    if sp11 < 0.02:
        sp11 = 0.02
    elif sp11 > 0.98:
        sp11 = 0.98

    rem = 100 - n
    V00 = 0.0
    V01 = 0.0
    V10 = 0.0
    V11 = 0.0

    for _ in range(rem - 1):
        p = sp00
        c00 = 3.0 * p + p * V00 + (1.0 - p) * V01
        d00 = 1.0 + 4.0 * p + p * V10 + (1.0 - p) * V11
        NV00 = d00 if d00 > c00 else c00

        p = sp01
        c01 = 3.0 * p + p * V00 + (1.0 - p) * V01
        d01 = 1.0 + 4.0 * p + p * V10 + (1.0 - p) * V11
        NV01 = d01 if d01 > c01 else c01

        p = sp10
        c10 = 3.0 * p + p * V00 + (1.0 - p) * V01
        d10 = 1.0 + 4.0 * p + p * V10 + (1.0 - p) * V11
        NV10 = d10 if d10 > c10 else c10

        p = sp11
        c11 = 3.0 * p + p * V00 + (1.0 - p) * V01
        d11 = 1.0 + 4.0 * p + p * V10 + (1.0 - p) * V11
        NV11 = d11 if d11 > c11 else c11

        V00, V01, V10, V11 = NV00, NV01, NV10, NV11

    if last_me == 'C':
        if last_opp == 'C':
            p = sp00
        else:
            p = sp01
    else:
        if last_opp == 'C':
            p = sp10
        else:
            p = sp11

    value_c = 3.0 * p + p * V00 + (1.0 - p) * V01
    value_d = 1.0 + 4.0 * p + p * V10 + (1.0 - p) * V11

    if value_d > value_c:
        return 'D'
    return 'C'
